        fn template(uri: &str) -> Self {
            Self {
                kind: "compose.kit_backbone.dev_json".to_string(),
                schema: "2026-05-06".to_string(),
                connection_uri: uri.to_string(),
                persistence: DevJsonPersistenceNotes {
                    atomic_rewrite: "Serialize full document to <path>.tmp.compose-write in the same directory, fsync, then atomic rename(2) over <path>.".to_string(),
                    crash_safety: "Readers never observe a partial JSON object: they keep the last fully-renamed file. A crash may leave an orphan temp file to delete manually.".to_string(),
                },
                semantic_op_log: Vec::new(),
            }
        }
    }
    //#endregion 🧾 wire format

    //#region 🧭 paths + uri
    pub fn normalize_connection_uri(raw: &str) -> String {
        raw.trim().to_string()
    }

    pub fn filesystem_path_from_uri(uri: &str) -> Result<PathBuf, ComposeError> {
        let u = uri.trim();
        let p = if let Some(r) = u.strip_prefix("file://") { r } else { u };
        if p.is_empty() {
            return Err(ComposeError::invalid("empty backbone connectionUri"));
        }
        Ok(PathBuf::from(p))
    }

    fn resolve_local_compose_root(project_or_dot_compose: &Path) -> PathBuf {
        if project_or_dot_compose.file_name().and_then(|s| s.to_str()) == Some(".compose") {
            project_or_dot_compose.to_path_buf()
        } else {
            project_or_dot_compose.join(".compose")
        }
    }

    fn init_local_dot_compose_layout(compose_root: &Path) -> Result<(), ComposeError> {
        std::fs::create_dir_all(compose_root).map_err(|e| ComposeError::invalid(format!("create .compose root: {e}")))?;
        std::fs::create_dir_all(compose_root.join("blobs")).map_err(|e| ComposeError::invalid(format!("create blobs dir: {e}")))?;
        let ddl = r#"
CREATE TABLE IF NOT EXISTS semantic_op_log (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  draft_id TEXT NOT NULL,
  transaction_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  input_json TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS conflict_stub (
  id INTEGER PRIMARY KEY
);
"#;
        for name in ["wip.db", "staged.db", "authoritative.db", "conflicts.db"] {
            let db = compose_root.join(name);
            let conn = Connection::open(&db).map_err(|e| ComposeError::invalid(format!("open {name}: {e}")))?;
            conn.execute_batch(ddl).map_err(|e| ComposeError::invalid(format!("init {name}: {e}")))?;
        }
        Ok(())
    }

    fn db_file_for_child(compose_root: &Path, child_label: &'static str) -> Result<PathBuf, ComposeError> {
        let name = match child_label {
            "wip" => "wip.db",
            "auth" => "authoritative.db",
            other => return Err(ComposeError::invalid(format!("unknown child label `{other}` for local backbone"))),
        };
        Ok(compose_root.join(name))
    }
    //#endregion 🧭 paths + uri

    //#region ✍️ atomic json
    fn atomic_write_json(path: &Path, doc: &DevJsonBackboneFile) -> Result<(), ComposeError> {
        let parent = path.parent().ok_or_else(|| ComposeError::invalid("dev json path has no parent directory"))?;
        std::fs::create_dir_all(parent).map_err(|e| ComposeError::invalid(format!("create dev json parent: {e}")))?;
        let tmp = path.with_extension("tmp.compose-write");
        let body = serde_json::to_string_pretty(doc).map_err(|e| ComposeError::invalid(e.to_string()))?;
        std::fs::write(&tmp, body).map_err(|e| ComposeError::invalid(format!("write temp dev json: {e}")))?;
        std::fs::rename(&tmp, path).map_err(|e| ComposeError::invalid(format!("rename dev json: {e}")))?;
        Ok(())
    }

    fn read_or_init_dev_json(path: &Path, uri: &str) -> Result<DevJsonBackboneFile, ComposeError> {
        if !path.exists() {
            return Ok(DevJsonBackboneFile::template(uri));
        }
        let s = std::fs::read_to_string(path).map_err(|e| ComposeError::invalid(format!("read dev json: {e}")))?;
        serde_json::from_str(&s).map_err(|e| ComposeError::invalid(format!("parse dev json: {e}")))
    }
    //#endregion ✍️ atomic json

    //#region 🔁 replay
    pub async fn replay_stored_ops(graph: &Arc<Graph>, ops: &[StoredSemanticOp]) -> Result<(), ComposeError> {
        graph.the_kit.clear_piece_projections_for_backbone_replay().await;
        for op in ops {
            let draft_id = Id::from(op.draft_id.as_str());
            let transaction_id = Id::from(op.transaction_id.as_str());
            let payload = serde_json::to_string(&op.input).map_err(|e| ComposeError::invalid(e.to_string()))?;
            crate::kit_graph_engine::apply_semantic_op_json(graph, &draft_id, &transaction_id, op.kind.as_str(), &payload).await?;
        }
        Ok(())
    }
    //#endregion 🔁 replay

    //#region 🧩 attached variants
    pub struct DevJsonAttached {
        path: PathBuf,
        connection_uri_normalized: String,
    }

    impl DevJsonAttached {
        fn read_doc(&self) -> Result<DevJsonBackboneFile, ComposeError> {
            read_or_init_dev_json(&self.path, &self.connection_uri_normalized)
        }

        pub fn append_op(&mut self, draft_id: &Id, transaction_id: &Id, kind: &str, input: &serde_json::Value) -> Result<(), ComposeError> {
            let mut doc = self.read_doc()?;
            doc.semantic_op_log.push(StoredSemanticOp {
                draft_id: draft_id.to_string(),
                transaction_id: transaction_id.to_string(),
                kind: kind.to_string(),
                input: input.clone(),
            });
            atomic_write_json(&self.path, &doc)
        }
    }

    pub struct LocalAttached {
        compose_root: PathBuf,
        db_path: PathBuf,
        connection_uri_normalized: String,
    }

    impl LocalAttached {
        pub fn append_op(&mut self, draft_id: &Id, transaction_id: &Id, kind: &str, input: &serde_json::Value) -> Result<(), ComposeError> {
            let conn = Connection::open(&self.db_path).map_err(|e| ComposeError::invalid(format!("sqlite append: {e}")))?;
            let input_json = serde_json::to_string(input).map_err(|e| ComposeError::invalid(e.to_string()))?;
            conn.execute(
                "INSERT INTO semantic_op_log (draft_id, transaction_id, kind, input_json) VALUES (?1, ?2, ?3, ?4)",
                rusqlite::params![draft_id.as_str(), transaction_id.as_str(), kind, input_json],
            )
            .map_err(|e| ComposeError::invalid(format!("sqlite insert: {e}")))?;
            Ok(())
        }

        fn load_ops(&self) -> Result<Vec<StoredSemanticOp>, ComposeError> {
            let conn = Connection::open(&self.db_path).map_err(|e| ComposeError::invalid(format!("sqlite read: {e}")))?;
            let mut stmt = conn
                .prepare("SELECT draft_id, transaction_id, kind, input_json FROM semantic_op_log ORDER BY seq ASC")
                .map_err(|e| ComposeError::invalid(format!("sqlite prepare: {e}")))?;
            let rows = stmt
                .query_map([], |row| {
                    let input_json: String = row.get(3)?;
                    let input: serde_json::Value = serde_json::from_str(&input_json).map_err(|e| rusqlite::Error::ToSqlConversionFailure(Box::new(e)))?;
                    Ok(StoredSemanticOp {
                        draft_id: row.get(0)?,
                        transaction_id: row.get(1)?,
                        kind: row.get(2)?,
                        input,
                    })
                })
                .map_err(|e| ComposeError::invalid(format!("sqlite query: {e}")))?;
            let mut out = Vec::new();
            for r in rows {
                out.push(r.map_err(|e| ComposeError::invalid(format!("sqlite row: {e}")))?);
            }
            Ok(out)
        }
    }

    pub enum AttachedBackbone {
        DevJson(DevJsonAttached),
        Local(LocalAttached),
    }

    impl AttachedBackbone {
        pub async fn mount_and_replay(connection_uri: &str, store_kind: BackboneStoreKind, child_label: &'static str, graph: &Arc<Graph>) -> Result<Self, ComposeError> {
            let norm = normalize_connection_uri(connection_uri);
            let path = filesystem_path_from_uri(&norm)?;
            let mut this = match store_kind {
                BackboneStoreKind::DevJson => Self::DevJson(DevJsonAttached { path, connection_uri_normalized: norm }),
                BackboneStoreKind::LocalDotCompose => {
                    let compose_root = resolve_local_compose_root(&path);
                    init_local_dot_compose_layout(&compose_root)?;
                    let db_path = db_file_for_child(&compose_root, child_label)?;
                    Self::Local(LocalAttached { compose_root, db_path, connection_uri_normalized: norm })
                }
            };
            this.replay_into_graph(graph).await?;
            Ok(this)
        }

        pub async fn replay_into_graph(&mut self, graph: &Arc<Graph>) -> Result<(), ComposeError> {
            let ops: Vec<StoredSemanticOp> = match self {
                AttachedBackbone::DevJson(d) => d.read_doc()?.semantic_op_log.clone(),
                AttachedBackbone::Local(l) => l.load_ops()?,
            };
            replay_stored_ops(graph, &ops).await
        }

        pub fn append_semantic_op(&mut self, draft_id: &Id, transaction_id: &Id, kind: &str, input: &serde_json::Value) -> Result<(), ComposeError> {
            match self {
                AttachedBackbone::DevJson(d) => d.append_op(draft_id, transaction_id, kind, input),
                AttachedBackbone::Local(l) => l.append_op(draft_id, transaction_id, kind, input),
            }
        }

        pub fn normalized_connection_uri(&self) -> &str {
            match self {
                AttachedBackbone::DevJson(d) => d.connection_uri_normalized.as_str(),
                AttachedBackbone::Local(l) => l.connection_uri_normalized.as_str(),
            }
        }
    }
    //#endregion 🧩 attached variants

    /// @emoji 🧪 Build [`StoredSemanticOp`] rows from `kit-store.golden.ops.compose.json` (US-001 fixture) for persistence tests.
    pub fn stored_ops_from_golden_ops_json(src: &serde_json::Value) -> Result<Vec<StoredSemanticOp>, ComposeError> {
        let draft_id = src["draftId"].as_str().ok_or_else(|| ComposeError::invalid("golden ops missing draftId"))?.to_string();
        let transaction_id = src["transactionId"].as_str().ok_or_else(|| ComposeError::invalid("golden ops missing transactionId"))?.to_string();
        let arr = src["ops"].as_array().ok_or_else(|| ComposeError::invalid("golden ops missing ops"))?;
        let mut out = Vec::new();
        for rec in arr {
            let kind = rec["kind"].as_str().ok_or_else(|| ComposeError::invalid("op.kind"))?;
            let input = rec.get("input").cloned().ok_or_else(|| ComposeError::invalid("op.input"))?;
            out.push(StoredSemanticOp { draft_id: draft_id.clone(), transaction_id: transaction_id.clone(), kind: kind.to_string(), input });
        }
        Ok(out)
    }
}

